<script>
import engine from "@/core/index";

const COLOR_PALETTE = ['#3f51b5', '#e53935', '#43a047', '#fb8c00', '#9c27b0', '#00838f', '#f9a825'];
const COLOR_DARK = ['#283593', '#b71c1c', '#2e7d32', '#e65100', '#6a1b9a', '#005662', '#f57f17'];

export default {
  name: "HomeAdmin",
  props: {
    userInfo: { type: Object, default: () => ({}) },
    allUsers: { type: Array, default: () => [] },
    congeTypes: { type: Array, default: () => [] },
  },
  data() {
    return {
      employeeSearch: "",
      selectedEmployee: null,
      showEmployeeDialog: false,
      selectedEmployeeCongeListe: [],
      selectedEmployeeSoldeListe: [],
      pendingCounts: {},
      hideZeroSoldeAdmin: true,
      showValidationModal: false,
      selectedRequest: null,
      isUpdating: false,
      congeHeaders: [
        { title: 'Type', key: 'id_conge_type', sortable: true },
        { title: 'Date début', key: 'debut_timestamp', sortable: true },
        { title: 'Date fin', key: 'fin_timestamp', sortable: true },
        { title: 'Jours', key: 'nbr_days', sortable: true },
        { title: 'Motif', key: 'commentaire', sortable: false },
        { title: 'Statut', key: 'statut', sortable: true },
      ],
    };
  },
  watch: {
    allUsers: {
      handler(users) {
        if (users && users.length > 0) this.fetchAllPendingCounts(users);
      },
      immediate: true,
    },
  },
  computed: {
    filteredEmployees() {
      const q = (this.employeeSearch || "").toLowerCase().trim();
      if (!q) return this.allUsers;
      return this.allUsers.filter(emp => {
        const name = (emp.user_name || "").toLowerCase();
        const service = (emp.service || "").toLowerCase();
        return name.includes(q) || service.includes(q);
      });
    },
    selectedEmployeePending() {
      return this.selectedEmployeeCongeListe.filter(c => c.statut == 0);
    },
    selectedEmployeeHistory() {
      return this.selectedEmployeeCongeListe.filter(c => c.statut > 0);
    },
  },
  methods: {
    employeeFirstName(emp) {
      return (emp.user_name || "").split(" ")[0] || "—";
    },
    employeeLastName(emp) {
      const parts = (emp.user_name || "").split(" ");
      return parts.slice(1).join(" ").toUpperCase() || "";
    },
    employeeInitials(emp) {
      return (emp.user_name || "")
        .split(" ")
        .map(w => w[0])
        .join("")
        .toUpperCase()
        .slice(0, 2) || "?";
    },
    employeeColorIndex(emp) {
      const key = emp.service || emp.user_name || "";
      let h = 0;
      for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) & 0xffff;
      return h % COLOR_PALETTE.length;
    },
    employeeColor(emp) { return COLOR_PALETTE[this.employeeColorIndex(emp)]; },
    employeeColorDark(emp) { return COLOR_DARK[this.employeeColorIndex(emp)]; },
    employeePendingCount(emp) {
      return this.pendingCounts[emp.user_id] || 0;
    },
    fetchAllPendingCounts(users) {
      let that = this;
      users.forEach(emp => {
        engine.get_conge_by_user_id(emp.user_id, function (data) {
          if (data.code == 0) {
            const count = data.data.data.data
              .map(v => v.fieldData)
              .filter(c => c.statut == 0).length;
            that.pendingCounts = { ...that.pendingCounts, [emp.user_id]: count };
          }
        });
      });
    },
    formatHireDate(emp) {
      const ts = parseInt(emp.date_embauche_timestamp);
      if (!ts) return "—";
      return new Date(ts * 1000).toLocaleDateString("fr-FR", { day: "2-digit", month: "long", year: "numeric" });
    },
    openEmployee(emp) {
      console.log("openEmployee", emp);

      this.selectedEmployee = emp;
      this.selectedEmployeeCongeListe = [];
      this.selectedEmployeeSoldeListe = [];
      this.showEmployeeDialog = true;
      let that = this;
      engine.get_conge_by_user_id(emp.user_id, function (data) {
        if (data.code == 0) {
          that.selectedEmployeeCongeListe = data.data.data.data.map(val => ({
            ...val.fieldData,
            _recordId: val.recordId,
          }));
        }
      });
      engine.get_solde_by_user_id(emp.user_id, function (data) {
        if (data.code == 0) {
          that.selectedEmployeeSoldeListe = data.data.data.data.map(val => val.fieldData);
        }
      });
    },
    openValidationModal(request) {
      this.selectedRequest = request;
      this.showValidationModal = true;
    },
    handleDecision(statut) {
      if (!this.selectedRequest?._recordId) return;
      this.isUpdating = true;
      let that = this;
      engine.update_conge_statut(this.selectedRequest._recordId, statut, function () {
        that.isUpdating = false;
        that.showValidationModal = false;
        that.selectedRequest = null;
        // Recharger les congés de l'employé
        engine.get_conge_by_user_id(that.selectedEmployee.user_id, function (data) {
          if (data.code == 0) {
            that.selectedEmployeeCongeListe = data.data.data.data.map(val => ({
              ...val.fieldData,
              _recordId: val.recordId,
            }));
          }
        });
        // Mettre à jour le badge de la carte employé
        engine.get_conge_by_user_id(that.selectedEmployee.user_id, function (data) {
          if (data.code == 0) {
            const count = data.data.data.data
              .map(v => v.fieldData)
              .filter(c => c.statut == 0).length;
            that.pendingCounts = { ...that.pendingCounts, [that.selectedEmployee.user_id]: count };
          }
        });
      });
    },
    getSoldeColor(solde) {
      const colorMap = {
        red: '#e53935', blue: '#3f51b5', green: '#43a047',
        orange: '#fb8c00', yellow: '#f9a825', purple: '#9c27b0',
        gray: '#757575', grey: '#757575', pink: '#e91e63',
        teal: '#00838f', cyan: '#00acc1', indigo: '#3f51b5',
      };
      const found = this.congeTypes.find(t => t.id_conge_type === solde.id_conge_type);
      if (!found) return '#3f51b5';
      return colorMap[found.color] || found.color || '#3f51b5';
    },
    getTypeName(id) {
      const found = this.congeTypes.find(t => t.id_conge_type === id);
      return found ? found.libelle : id || "—";
    },
    getTypeColor(id) {
      const colorMap = {
        red: '#e53935', blue: '#3f51b5', green: '#43a047',
        orange: '#fb8c00', yellow: '#f9a825', purple: '#9c27b0',
        gray: '#757575', grey: '#757575', pink: '#e91e63',
        teal: '#00838f', cyan: '#00acc1', indigo: '#3f51b5',
      };
      const found = this.congeTypes.find(t => t.id_conge_type === id);
      if (!found) return '#757575';
      return colorMap[found.color] || found.color || '#757575';
    },
    formatDate(ts) {
      if (!ts) return "—";
      return new Date(parseInt(ts) * 1).toLocaleDateString("fr-FR", {
        day: "2-digit", month: "2-digit", year: "numeric",
      });
    },
    parseMotif(commentaire) {
      if (!commentaire) return "—";
      try {
        const parsed = JSON.parse(commentaire);
        if (Array.isArray(parsed) && parsed[0]?.user) return parsed[0].user || "—";
      } catch {
        return commentaire;
      }
      return commentaire;
    },
  },
};
</script>

